// Parse both LLM responses, enforce platform limits, and build the Notion update payloads.
const out = [];
for (const item of $input.all()) {
  const meta = $('Map Notion properties').item.json;
  const brief = JSON.parse($('LLM · Content brief').item.json.choices[0].message.content);
  const d = JSON.parse(item.json.choices[0].message.content);

  const fit = (s, n) => { s = String(s || ''); return s.length <= n ? s : s.slice(0, n - 1).replace(/\s+\S*$/, '') + '…'; };
  // Notion rich_text: max 2000 chars per text object, so chunk long copy
  const rt = (s) => { s = String(s || ''); const parts = []; for (let i = 0; i < s.length && parts.length < 50; i += 1900) parts.push({ type: 'text', text: { content: s.slice(i, i + 1900) } }); return parts.length ? parts : [{ type: 'text', text: { content: '' } }]; };

  const xPost = fit(d.x?.post, 280);
  const thread = (d.x?.thread || []).slice(0, 3).map((t) => fit(t, 280));
  const slides = (d.instagram?.slides || []).slice(0, 6);
  const reel = (d.reel?.script || []).map((b) => `[${b.t}] ${b.voiceover}  (visual: ${b.visual})`).join('\n');
  const schedule = (d.schedule || []).slice(0, 7);

  // Next calendar date for the first suggested slot (workflow timezone)
  const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const first = schedule[0];
  let publishDate = null;
  if (first && DAYS.includes(first.day)) {
    const now = new Date();
    let diff = DAYS.indexOf(first.day) - ((now.getDay() + 6) % 7);
    if (diff <= 0) diff += 7;
    const dt = new Date(now.getFullYear(), now.getMonth(), now.getDate() + diff);
    const [h, m] = String(first.time || '09:00').split(':').map(Number);
    dt.setHours(h || 9, m || 0, 0, 0);
    publishDate = dt.toISOString();
  }

  const briefText = [`Angle: ${brief.angle}`, `Objective: ${brief.objective}`, `Key messages: ${(brief.keyMessages || []).join(' | ')}`, `CTA: ${brief.cta}`].join('\n');
  const properties = {
    Status: { status: { name: 'Review' } },
    Brief: { rich_text: rt(briefText) },
    'X Post': { rich_text: rt(xPost) },
    'X Thread': { rich_text: rt(thread.join('\n\n')) },
    LinkedIn: { rich_text: rt(d.linkedin?.post) },
    'IG Carousel': { rich_text: rt(slides.map((s, i) => `${i + 1}. ${s}`).join('\n') + '\n\n' + (d.instagram?.caption || '') + '\n' + (d.instagram?.hashtags || []).join(' ')) },
    'Reel Script': { rich_text: rt(`Hooks: ${(d.reel?.hooks || []).join(' / ')}\n${reel}`) },
    Schedule: { rich_text: rt(schedule.map((s) => `${s.day} ${s.time} · ${s.channel}: ${s.why}`).join('\n')) },
    Channels: { multi_select: [...new Set(schedule.map((s) => s.channel))].map((name) => ({ name })) },
  };
  if (publishDate) properties['Publish date'] = { date: { start: publishDate } };

  const h2 = (t) => ({ object: 'block', type: 'heading_2', heading_2: { rich_text: rt(t) } });
  const p = (t) => ({ object: 'block', type: 'paragraph', paragraph: { rich_text: rt(t) } });
  const children = [
    h2('Content brief'), p(briefText),
    h2('X'), p(xPost), ...thread.map(p),
    h2('LinkedIn'), p(d.linkedin?.post),
    h2('Instagram carousel'), ...slides.map((s, i) => p(`Slide ${i + 1}: ${s}`)), p(d.instagram?.caption), p((d.instagram?.hashtags || []).join(' ')),
    h2('Reel (30s)'), p(reel),
  ];

  out.push({ json: { pageId: meta.pageId, pageUrl: meta.pageUrl, title: brief.title || meta.idea, idea: meta.idea, xPost, firstSlot: first ? `${first.day} ${first.time} (${first.channel})` : 'not set', properties, children } });
}
return out;
